import{limitRemainingMs,pickRecorderMimeType}from'./recorderState.js';
export const takeMs=(t)=>t.banked+(t.since?performance.now()-t.since:0);
export function stopTracks(stream){
stream.getTracks().forEach((track)=>{
try{
track.stop();
}
catch{}
});
}
export function closeContext(ctx){
if(!ctx)
return;
try{
void ctx.close().catch(()=>{});
}
catch{}
}
export function releaseTake(t){
if(t.released)
return;
t.released=true;
if(t.timer!==null){
clearInterval(t.timer);
t.timer=null;
}
if(t.limitTimer!==null){
clearTimeout(t.limitTimer);
t.limitTimer=null;
}
t.trackListeners.forEach(({track,listener})=>{
try{
track.removeEventListener('ended',listener);
}
catch{}
});
t.trackListeners=[];
stopTracks(t.stream);
closeContext(t.ctx);
t.ctx=null;
}
export function detachRecorder(t){
t.recorder.ondataavailable=null;
t.recorder.onstop=null;
t.recorder.onerror=null;
}
export function createTake(attempt,stream,onFail){
const mime=pickRecorderMimeType((type)=>MediaRecorder.isTypeSupported?.(type)??false);
const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);
const t={
attempt,stream,recorder,ctx:null,analyser:null,buffer:new Float32Array(0),
chunks:[],peaks:[],timer:null,limitTimer:null,banked:0,since:0,mime,
lastSecond:0,released:false,failed:false,discarded:false,finalized:false,trackListeners:[],
};
recorder.ondataavailable=(e)=>{
if(!t.failed&&!t.discarded&&!t.finalized&&e.data.size)
t.chunks.push(e.data);
};
recorder.onerror=()=>onFail(t);
try{
const Ctor=window.AudioContext??window.webkitAudioContext;
if(Ctor){
const ctx=new Ctor();
t.ctx=ctx;
try{
const analyser=ctx.createAnalyser();
analyser.fftSize=1024;
ctx.createMediaStreamSource(stream).connect(analyser);
void ctx.resume?.().catch(()=>{});
t.analyser=analyser;
t.buffer=new Float32Array(analyser.fftSize);
}
catch{
closeContext(ctx);
t.ctx=null;
t.analyser=null;
t.buffer=new Float32Array(0);
}
}
}
catch{}
return t;
}
export function requestMediaTake(params){
const{mine,currentAttempt,mounted,take,ownedTakes,getLimit,send,announce,sample,finishLimit,fail}=params;
const media=typeof navigator==='undefined'?undefined:navigator.mediaDevices;
if(!media?.getUserMedia||typeof MediaRecorder==='undefined'){
currentAttempt.current=null;
send({type:'unsupported'});
announce('unsupported');
return;
}
let request;
try{
request=media.getUserMedia({audio:true});
}
catch{
fail();
return;
}
Promise.resolve(request).then((stream)=>{
if(mine!==currentAttempt.current||!mounted.current){
stopTracks(stream);
return;
}
let t=null;
try{
t=createTake(mine,stream,fail);
take.current=t;
ownedTakes.current.add(t);
t.recorder.start();
if(t.failed||t.discarded||t.released)
return;
t.since=performance.now();
t.timer=setInterval(()=>sample(t),50);
t.limitTimer=setTimeout(()=>{if(take.current===t)
finishLimit();},limitRemainingMs(0,getLimit()));
stream.getAudioTracks().forEach((track)=>{
const listener=()=>{if(ownedTakes.current.has(t)&&!t.released)
fail(t);};
track.addEventListener('ended',listener);
t.trackListeners.push({track,listener});
if(track.readyState==='ended')
listener();
});
if(t.failed||t.discarded||t.released)
return;
send({type:'granted'});
announce('recording');
}
catch{
if(t)
fail(t);
else{
stopTracks(stream);
fail();
}
}
},(err)=>{
if(mine!==currentAttempt.current)
return;
const name=err?.name;
if(name==='NotAllowedError'||name==='SecurityError'||name==='PermissionDeniedError'){
currentAttempt.current=null;
send({type:'denied'});
announce('denied');
}
else if(name==='NotFoundError'||name==='TypeError'){
currentAttempt.current=null;
send({type:'unsupported'});
announce('unsupported');
}
else
fail();
});
}
